39	function compileFormSchema(node) {
40	  if (!Object.hasOwn(node, 'schema') || node.schema === undefined) return null;
41	  if (!isUsableObject(node.schema)) {
42	    throw new Error(`form node ${node.id}: schema must be an object`);
43	  }
44	  if (!Array.isArray(node.schema.fields)) {
45	    throw new Error(`form node ${node.id}: schema.fields must be an array`);
46	  }
47	
48	  const seenSegments = [];
49	  const compiled = [];
50	  node.schema.fields.forEach((field, index) => {
51	    const label = `form node ${node.id} field ${field && isUsableObject(field) && typeof field.path === 'string' && field.path ? field.path : `#${index}`}`;
52	    if (!isUsableObject(field)) {
53	      throw new Error(`${label}: field must be an object`);
54	    }
55	    if (typeof field.path !== 'string' || field.path.length === 0) {
56	      throw new Error(`form node ${node.id} field #${index}: path must be a non-empty string`);
57	    }
58	    const segments = field.path.split('.');
59	    if (segments.some(part => part.length === 0)) {
60	      throw new Error(`${label}: path must not contain empty segments`);
61	    }
62	    if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
63	      throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
64	    }
65	    for (const previous of seenSegments) {
66	      const shared = Math.min(previous.length, segments.length);
67	      let prefix = true;
68	      for (let i = 0; i < shared; i += 1) {
69	        if (previous[i] !== segments[i]) { prefix = false; break; }
70	      }
71	      if (prefix && previous.length === segments.length) {
72	        throw new Error(`${label}: duplicate field path`);
73	      }
74	      if (prefix) {
75	        throw new Error(`${label}: field paths must not be parent and child of each other`);
76	      }
77	    }
78	    seenSegments.push(segments);
79	
80	    if (!FIELD_TYPES.has(field.type)) {
81	      throw new Error(`${label}: unknown field type ${field.type}`);
82	    }
83	    const spec = { path: field.path, segments, type: field.type, required: false, hasDefault: false };
84	
85	    if (Object.hasOwn(field, 'required')) {
86	      if (typeof field.required !== 'boolean') {
87	        throw new Error(`${label}: required must be a boolean`);
88	      }
89	      spec.required = field.required;
90	    }
91	
92	    const applicableBounds = field.type === 'string' ? STRING_BOUNDS
93	      : (field.type === 'number' || field.type === 'integer') ? NUMBER_BOUNDS
94	      : new Set();
95	    for (const bound of ['minLength', 'maxLength', 'min', 'max']) {
96	      if (!Object.hasOwn(field, bound) || field[bound] === undefined) continue;
97	      if (!applicableBounds.has(bound)) {
98	        throw new Error(`${label}: ${bound} does not apply to ${field.type} fields`);
99	      }
100	      const value = field[bound];
101	      if (field.type === 'string') {
102	        if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
103	          throw new Error(`${label}: ${bound} must be a non-negative integer`);
104	        }
105	      } else if (typeof value !== 'number' || !Number.isFinite(value)) {
106	        throw new Error(`${label}: ${bound} must be a finite number`);
107	      }
108	      spec[bound] = value;
109	    }
110	    if (spec.minLength !== undefined && spec.maxLength !== undefined && spec.minLength > spec.maxLength) {
111	      throw new Error(`${label}: minLength must not be greater than maxLength`);
112	    }
113	    if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
114	      throw new Error(`${label}: min must not be greater than max`);
115	    }
116	
117	    if (Object.hasOwn(field, 'default') && field.default !== undefined) {
118	      const fallback = field.default;
119	      if (!valueMatchesType(fallback, spec.type)) {
120	        throw new Error(`${label}: default value does not match field type ${spec.type}`);
121	      }
122	      if (!valueSatisfiesBounds(fallback, spec)) {
123	        throw new Error(`${label}: default value violates field constraints`);
124	      }
125	      spec.hasDefault = true;
126	      spec.default = fallback;
127	    }
128	
129	    compiled.push(spec);
130	  });
131	
132	  return compiled;
133	}
