190	// Walks every condition node (including untaken branches) and turns it into a
191	// pre-validated, pre-resolved structure. Any malformed condition throws with a
192	// node id and a `$`-style child position, before the workflow can execute.
193	function compileCondition(condition, nodes, nodeId, position = '$', depth = 1) {
194	  if (depth > MAX_CONDITION_DEPTH) {
195	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
196	  }
197	  if (!isUsableObject(condition)) {
198	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
199	  }
200	
201	  const comboKeys = [];
202	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
203	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
204	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
205	  if (comboKeys.length > 1) {
206	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
207	  }
208	
209	  const comparisonKeys = ['field', 'outputField', 'operator', 'value', 'valueField', 'valueOutputField'];
210	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
211	
212	  if (comboKeys.length === 1) {
213	    if (presentComparisonKeys.length > 0) {
214	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, outputField, operator, value, valueField or valueOutputField`);
215	    }
216	    const key = comboKeys[0];
217	    if (key === 'not') {
218	      return { kind: 'not', child: compileCondition(condition.not, nodes, nodeId, `${position}.not`, depth + 1) };
219	    }
220	    const childList = condition[key];
221	    if (!Array.isArray(childList)) {
222	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
223	    }
224	    if (childList.length === 0) {
225	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
226	    }
227	    // A non-empty array may still carry length without a condition at every
228	    // slot: a child deleted through the JavaScript API can leave a hole, or
229	    // the array may have been allocated with gaps only. A missing slot is a
230	    // definition error at its own original index — it is never treated as
231	    // false, skipped over or filled in — so it is reported even when an
232	    // earlier sibling would already short-circuit the compound. Explicit
233	    // undefined/null entries are not holes: they remain present and fall
234	    // through to the ordinary "condition must be an object" rejection.
235	    const children = [];
236	    for (let index = 0; index < childList.length; index += 1) {
237	      if (!Object.hasOwn(childList, index)) {
238	        throw new Error(`condition node ${nodeId} at ${position}.${key}[${index}]: ${key}[${index}] is a missing child condition`);
239	      }
240	      children.push(
241	        compileCondition(childList[index], nodes, nodeId, `${position}.${key}[${index}]`, depth + 1));
242	    }
243	    return { kind: key, children };
244	  }
245	
246	  const where = `condition node ${nodeId} at ${position}`;
247	  const hasField = Object.hasOwn(condition, 'field');
248	  const hasOutputField = Object.hasOwn(condition, 'outputField');
249	  if ((!hasField && !hasOutputField) || !Object.hasOwn(condition, 'operator')) {
250	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
251	  }
252	  if (hasField && hasOutputField) {
253	    throw new Error(`${where}: condition must specify exactly one of field or outputField`);
254	  }
255	
256	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
257	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
258	  }
259	
260	  let left;
261	  if (hasField) {
262	    left = { kind: 'input', label: 'field', segments: parsePathSegments(condition.field, `${where} field`) };
263	  } else {
264	    left = {
265	      kind: 'output', label: 'outputField',
266	      ref: compileOutputReference(condition.outputField, nodes, `${where} outputField`),
267	    };
268	  }
269	
270	  if (condition.operator === 'exists') {
271	    const unexpected = presentComparisonKeys.filter(key =>
272	      key === 'value' || key === 'valueField' || key === 'valueOutputField');
273	    if (unexpected.length > 0) {
274	      throw new Error(`${where}: exists only takes field and operator (outputField may name the left side)`);
275	    }
276	    return { kind: 'comparison', operator: 'exists', left };
277	  }
278	
279	  const hasValue = Object.hasOwn(condition, 'value');
280	  const hasValueField = Object.hasOwn(condition, 'valueField');
281	  const hasValueOutput = Object.hasOwn(condition, 'valueOutputField');
282	  const rightCount = [hasValue, hasValueField, hasValueOutput].filter(Boolean).length;
283	  if (rightCount !== 1) {
284	    throw new Error(`${where}: condition must specify exactly one of value or valueField (or valueOutputField)`);
285	  }
286	
287	  let right;
288	  if (hasValue) {
289	    if (!isComparableConstant(condition.value)) {
290	      throw new Error(`${where}: value must be a string, finite number, boolean or null`);
291	    }
292	    right = { kind: 'constant', label: 'value', value: condition.value };
293	    if (condition.operator !== 'eq') {
294	      const numericValue = toComparableNumber(condition.value);
295	      if (numericValue === null) {
296	        throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
297	      }
298	      right.numericValue = numericValue;
299	    }
300	  } else if (hasValueField) {
301	    if (typeof condition.valueField !== 'string') {
302	      throw new Error(`${where} valueField: path must be a non-empty string`);
303	    }
304	    right = {
305	      kind: 'input', label: 'valueField',
306	      segments: parsePathSegments(condition.valueField, `${where} valueField`),
307	    };
308	  } else {
309	    right = {
310	      kind: 'output', label: 'valueOutputField',
311	      ref: compileOutputReference(condition.valueOutputField, nodes, `${where} valueOutputField`),
312	    };
313	  }
314	
315	  return { kind: 'comparison', operator: condition.operator, left, right };
316	}
