322	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
323	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
324	
325	function isIntegerIn(value, min, max) {
326	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
327	}
