329	// A retry block is either absent (one attempt, no waiting) or present with all
330	// four parameters together, each within the same ranges the engine enforces
331	// for business action retries and compensation retries alike.
332	function compileRetry(config, label) {
333	  if (!isUsableObject(config)) {
334	    throw new Error(`${label}: retry must be an object`);
335	  }
336	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
337	  if (missing.length > 0) {
338	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
339	  }
340	  if (!isIntegerIn(config.attempts, 1, 10)) {
341	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
342	  }
343	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
344	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
345	  }
346	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
347	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
348	  }
349	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
350	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
351	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
352	  }
353	  if (config.maxDelayMs < config.initialDelayMs) {
354	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
355	  }
356	  return {
357	    attempts: config.attempts,
358	    initialDelayMs: config.initialDelayMs,
359	    backoffFactor: config.backoffFactor,
360	    maxDelayMs: config.maxDelayMs,
361	  };
362	}
363	
364	// An action node either keeps the legacy `message` behavior, names a business
365	// operation the caller supplies at run time, and/or declares a compensation
366	// operation that undoes its business effect. Both retry blocks are optional
367	// and, absent, mean exactly one attempt with no waiting.
368	function compileAction(node) {
369	  let name = null;
370	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
371	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
372	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
373	    }
374	    name = node.operation;
375	  }
376	
377	  let retry = { ...DEFAULT_RETRY };
378	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
379	    if (!name) {
380	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
381	    }
382	    retry = compileRetry(node.retry, `action node ${node.id}`);
383	  }
384	
385	  let compensation = null;
386	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
387	    if (!isUsableObject(node.compensation)) {
388	      throw new Error(`action node ${node.id}: compensation must be an object`);
389	    }
390	    if (!name) {
391	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
392	    }
393	    const config = node.compensation;
394	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
395	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
396	    }
397	    let compRetry = { ...DEFAULT_RETRY };
398	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
399	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
400	    }
401	    compensation = { name: config.operation, retry: compRetry };
402	  }
403	
404	  // A legacy message action (no operation) is validated through the single
405	  // configured-value gate (assertConfiguredCopy below) — the same rule, with
406	  // action-specific wording, that end-node results use — covering every
407	  // message action including ones on untaken branches and entry-unreachable
408	  // ones. An action that names an operation ignores its message entirely, so
409	  // an unused uncloneable or shared-memory message is never rejected for it.
410	  // The gate only proves the message was safe as it was then; the same rule
411	  // is re-enforced at the action's own execution moment by readConfiguredCopy.
412	  if (name === null) {
413	    assertConfiguredCopy(node, 'message', ACTION_MESSAGE_COPY_ERRORS);
414	  }
415	
416	  return { name, retry, compensation };
417	}
418	
419	// The two failure kinds a node-configured value can produce, shared by
420	// definition validation (assertConfiguredCopy below) and the execution-time
421	// capture (readConfiguredCopy below): the value cannot be structured-cloned at
422	// all, or it clones but the clone retains shared memory. Uncloneability takes
423	// precedence when a value carries both, at both moments. Each node kind keeps
424	// its own wording — an action's message and an end node's result fail with the
425	// node-specific text the entries already exposed — and its own default for a
426	// value that is absent, undefined or null (action:<node id> for a legacy
427	// message; null for an end result), while "", 0 and false pass through
428	// untouched for both.
429	const ACTION_MESSAGE_COPY_ERRORS = {
430	  uncloneable: nodeId =>
431	    `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`,
432	  sharedMemory: nodeId =>
433	    `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`,
434	};
435	const END_RESULT_COPY_ERRORS = {
436	  uncloneable: nodeId =>
437	    `end node ${nodeId}: result must be a structured-cloneable value (objects and arrays must not contain functions)`,
438	  sharedMemory: nodeId =>
439	    `end node ${nodeId}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`,
440	};
441	
442	// The single independent-copy rule for a value a node configures — a legacy
443	// action's `message` and an end node's `result` both go through here, so the
444	// cloneability and retained-shared-memory rules are maintained in exactly one
445	// place and the two node kinds can never drift apart. It is invoked at two
446	// moments, and each moment keeps its original root-read protocol:
447	//
448	//  1. At validation time (assertConfiguredCopy), for every such node in the
449	//     definition — including nodes on untaken branches and nodes the entry
450	//     cannot reach — so a statically invalid value is rejected before any
451	//     node, business operation or compensation can run. An absent own
452	//     property is not read at all; the gate performs the first root read and
453	//     only an own, defined value reaches the clone, which performs the root's
454	//     second read itself (a throwing root accessor propagates from the gate
455	//     exactly as before).
456	//  2. At the node's own execution moment (readConfiguredCopy), against the
457	//     value actually about to be saved: the root is read exactly once and the
458	//     value that read produced is cloned, so validation cannot pin the result
459	//     — an enumerable getter's later answer and a preceding business
460	//     operation's or another activated branch's mutation are both captured.
461	//
462	// At either moment every nested enumerable accessor is read only by
463	// structuredClone's own read — there is no separate inspection pass over the
464	// original, so a getter's return order is never disturbed and the value the
465	// clone's read produced is both what is judged and what is saved (a legal
466	// value whose getter answers with a different ordinary value at execution
467	// time records that fresh value rather than the stale validation-time one). A
468	// root getter that throws on execution's single read, a nested getter that
469	// throws while the clone reads it, and a value that cannot be cloned at all
470	// (a bare function) all surface as the same uncloneable error.
471	//
472	// The copy itself is produced by independentCopy — the one clone-then-judge
473	// rule every saved value in this engine goes through (see its comment for why
474	// cloning must precede the shared-memory traversal and why uncloneability
475	// takes precedence). Only the wording of the failure is node-specific here.
476	//
477	// Any failure is thrown as an ordinary Error naming the node (errors[kind])
478	// rather than recorded as a run status: the synchronous entry propagates it
479	// and the asynchronous entry's rejected Promise carries it. It is never an
480	// action_failed — neither node kind has a retry budget — it neither consumes
481	// business-action retries nor triggers compensation, and no output/result is
482	// recorded for the node. At execution, an absent, undefined or null value
483	// becomes `absentValue` (action:<node id> for messages, null for results),
484	// while "", 0 and false pass through untouched.
485	function configuredCopy(node, property, errors, options) {
486	  const validation = options !== undefined && options.validation === true;
487	
488	  if (validation) {
489	    // Preserve the validation gate exactly: no read at all for a missing own
490	    // property, one unguarded gate read (a throwing root accessor propagates
491	    // raw, as the former per-node gates did), and an undefined value is left
492	    // to execution. The structuredClone argument evaluation is the root's
493	    // second — and final — read this moment; the clone itself traverses that
494	    // captured value (firing nested getters once), so no read the original
495	    // gate made is added or removed.
496	    if (!Object.hasOwn(node, property)) return;
497	    const gated = node[property];
498	    if (gated === undefined) return;
499	    const copy = independentCopy(node[property]);
500	    if (!copy.ok) throw new Error(errors[copy.reason](node.id));
501	    return;
502	  }
503	
504	  // Execution: the root value's single read. An absent, undefined or null
505	  // value takes the node kind's default (action:<node id> for messages, null
506	  // for results) without reaching structuredClone; a root getter that throws
507	  // on this read is the uncloneable error.
