1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync } from '../src/engine.js';
4	
5	// Regression coverage for defaults a successful form attaches to a host object
6	// (a Date) during a run. Forms apply defaults directly on the live run input,
7	// so context.input and later conditions always saw them; but business-action
8	// argument copies and compensation snapshots used to be plain structured
9	// clones, and structuredClone reproduces a Date from its time value alone,
10	// silently dropping every attached own property — so the action and its
11	// compensation lost exactly the run-time form defaults. These tests pin the
12	// fix: the same defaults are visible in every copy, the Date keeps its type
13	// and time, aliases stay aliases within one copy, and every copy is
14	// independent of the run input, the caller's input and every other copy.
15	
16	const WHEN = Date.parse('2024-01-02T03:04:05.000Z');
17	
18	// start -> form-one (adds defaults, including onto the input Date)
19	//       -> act (business + compensation in async runs; a message in sync)
20	//       -> check (condition reading a default attached to the Date)
21	//       -> seen / missed (two ends)
22	function dateDefaultWorkflow(actNode) {
23	  return {
24	    id: 'date-form-defaults',
25	    entry: 'start',
26	    nodes: [
27	      { id: 'start', type: 'trigger', next: 'form-one' },
28	      { id: 'form-one', type: 'form', next: 'act', schema: { fields: [
29	        // A default landing directly on the caller's Date.
30	        { path: 'request.createdAt.channel', type: 'string', default: 'web' },
31	        // A multi-level path where every parent above the leaf is created on
32	        // the Date during the run.
33	        { path: 'request.createdAt.meta.source', type: 'string', default: 'form' },
34	        { path: 'request.createdAt.meta.kind', type: 'string', default: 'kind-default' },
35	        // Plain-object defaults keep their existing behavior.
36	        { path: 'plain.pair.x', type: 'string', default: 'X' },
37	      ] } },
38	      actNode,
39	      {
40	        id: 'check', type: 'condition', then: 'seen', else: 'missed',
41	        condition: { all: [
42	          { field: 'request.createdAt.channel', operator: 'eq', value: 'web' },
43	          { field: 'request.createdAt.meta.source', operator: 'eq', value: 'form' },
44	        ] },
45	      },
46	      { id: 'seen', type: 'end', result: 'default-visible' },
47	      { id: 'missed', type: 'end', result: 'default-missing' },
48	    ],
49	  };
50	}
51	
52	// Two input fields point at the same Date; both must keep aliasing the one
53	// copied Date inside each independent copy.
54	function callerInput() {
55	  const createdAt = new Date(WHEN);
56	  return { request: { createdAt }, note: { at: createdAt } };
57	}
58	
59	function assertDateWithDefaults(input) {
60	  assert.ok(input.request.createdAt instanceof Date, 'the value stays a Date');
61	  assert.equal(input.request.createdAt.getTime(), WHEN, 'the Date keeps its time value');
62	  assert.equal(input.request.createdAt.channel, 'web');
63	  // The whole newly-created multi-level path is readable.
64	  assert.deepEqual(input.request.createdAt.meta, { source: 'form', kind: 'kind-default' });
65	  assert.equal(input.plain.pair.x, 'X');
66	}
