68	test('async: a business action reads defaults a form attached to a Date, with type and time preserved', async () => {
69	  const workflow = dateDefaultWorkflow({
70	    id: 'act', type: 'action', operation: 'op',
71	    compensation: { operation: 'undo' }, next: 'check',
72	  });
73	  const caller = callerInput();
74	  const seen = [];
75	  const result = await executeWorkflowAsync(workflow, caller, {
76	    op: (input, output, nodeId, attempt) => {
77	      seen.push({ alias: input.request.createdAt === input.note.at, output: structuredClone(output), nodeId, attempt });
78	      assertDateWithDefaults(input);
79	      // Two input fields aliasing one Date still alias the one copied Date
80	      // inside this invocation's copy.
81	      assert.equal(input.request.createdAt, input.note.at);
82	      assert.equal(input.note.at.meta.source, 'form');
83	      // The copy is independent of the caller's Date.
84	      assert.notEqual(input.request.createdAt, caller.request.createdAt);
85	      // Mutating this attempt's copy: the time, the attached defaults, the
86	      // created parent and a brand-new own property all stay within the copy.
